// Shapes of docs/data/history.json (watchlist) and docs/data/finder.json (deal finder),
// both generated by the Python side (src/hotelwatch/storage.py and finder.py).

export type Basis = "before_tax" | "after_tax";

export interface PlanRow {
  name: string;
  before_tax: number | null;
  after_tax: number | null;
  refundable: boolean;
  promo: string | null;
}

export interface Reading {
  t: string;
  price: number | null; // INR
  after_tax: number | null; // INR
  native: number | null;
  native_after_tax: number | null;
  fx_rate: number | null;
  plan: string | null;
  promo: string | null;
  available: boolean;
  plans: PlanRow[];
}

export interface TargetStats {
  current: number | null;
  current_native?: number | null;
  current_fx_rate?: number | null;
  current_after_tax?: number | null;
  current_plan?: string | null;
  current_promo?: string | null;
  available: boolean;
  lowest?: number;
  lowest_at?: string;
  highest?: number;
  first?: number;
  change_pct_vs_prev?: number | null;
  below_alert?: boolean;
  readings?: number;
}

export interface Target {
  id: string;
  name: string;
  url: string;
  provider: string;
  room: string;
  check_in: string;
  check_out: string;
  nights: number;
  adults: number;
  children: number[];
  rate_plan: string | null;
  alert_below: number | null;
  currency: string;
  price_basis: Basis;
  fx_rate: number | null;
  stats: TargetStats;
  readings: Reading[];
}

export interface ScanPoint {
  check_in: string;
  price: number | null; // INR
  native: number | null;
  plan: string | null;
  promo: string | null;
  available: boolean;
  fx_rate: number | null;
  t: string;
  h: [string, number | null][];
}

export interface ScanHistory {
  t: string;
  min: number | null;
  min_native?: number | null;
  min_date: string | null;
  median?: number | null;
  fx_rate?: number | null;
  available: number;
}

export interface Scan {
  id: string;
  name: string;
  url: string;
  provider: string;
  room: string;
  nights: number;
  from: string;
  to: string;
  adults: number;
  children: number[];
  rate_plan: string | null;
  currency: string;
  price_basis: Basis;
  fx_rate: number | null;
  latest: { run_at: string; failures: number; fresh: number; points: ScanPoint[] } | null;
  history: ScanHistory[];
}

export interface WatchData {
  generated_at: string;
  targets: Target[];
  scans: Scan[];
}

// ---- deal finder ----

export interface FinderDate {
  d: string;
  p: number | null;
  site: string | null;
  lo: number | null;
  hi: number | null;
  first: number | null;
  prev: number | null;
  seen: string | null;
}

export interface FinderHotel {
  key: string;
  location: string;
  name: string;
  type: string;
  rating: number;
  reviews: number;
  url: string;
  image: string | null;
  lat: number | null;
  lng: number | null;
  labels: string[];
  best: { check_in: string; total: number; nightly: number; site: string } | null;
  median_nightly: number | null;
  peer_median_nightly: number | null;
  peer_discount_pct: number | null;
  drop_pct: number | null;
  score: number;
  super_value: boolean;
  reasons: string[];
  dates: FinderDate[];
  history: { t: string; min: number | null }[];
}

export interface FinderLocation {
  id: string;
  name: string;
  country: string;
  hotels: number;
  priced: number;
  median_nightly: number | null;
  updated_at: string | null;
}

export interface FinderData {
  generated_at: string;
  config: {
    nights: number;
    adults: number;
    from: string;
    to: string;
    max_nightly_inr: number;
    min_rating: number;
    min_reviews: number;
  };
  locations: FinderLocation[];
  hotels: FinderHotel[];
}

// ---- derived ----

export interface HotelGroup {
  key: string;
  name: string;
  targets: Target[];
  scans: Scan[];
}

export type ChangeKind = "down" | "up" | "back" | "soldout";

export interface HistPoint {
  t: string;
  time: number;
  v: number | null;
}

export interface ScanRow {
  p: ScanPoint;
  date: string;
  h: HistPoint[];
  now: number | null;
  prev: number | null | undefined;
  changedAt: number | null;
  kind: ChangeKind | null;
  pct: number | null;
  lo: number | null;
  hi: number | null;
  distinct: number;
}
